import{_ as e,a as t,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"自动化任务：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","frontmatter":{"title":"自动化任务：发布、排障与恢复练习","description":"把维护动作、症状调查和同一故障场景的验收放在一起。","showdocs":{"topics":[{"id":"automation","title":"定时任务与自动化","link":"/topics/automation/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"自动化对象与任务理论课程","summary":"把维护动作、症状调查和同一故障场景的验收放在一起。","status":"active","related":[{"title":"自动化：按日期生成可重放报告","link":"/systems/shell-automation/automation/plus/practice/application","kind":"完整实践","scope":"general","audience":"general"},{"title":"自动化任务：基础对象与机制","link":"/systems/shell-automation/automation/task-contract","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"自动化：按日期生成可重放报告","link":"/systems/shell-automation/automation/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"自动化：按日期生成可重放报告","link":"/systems/shell-automation/automation/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/shell-automation/automation/operations.md","filePath":"systems/shell-automation/automation/operations.md"}'),o={name:"systems/shell-automation/automation/operations.md"};function n(s,a,l,p,c,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="自动化任务-发布、排障与恢复练习" tabindex="-1">自动化任务：发布、排障与恢复练习 <a class="header-anchor" href="#自动化任务-发布、排障与恢复练习" aria-label="Permalink to &quot;自动化任务：发布、排障与恢复练习&quot;">​</a></h1><h2 id="part-1" tabindex="-1">失败补跑、锁管理与恢复 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;失败补跑、锁管理与恢复 {#part-1}&quot;">​</a></h2><p>维护日期报告任务前先保存批次日期、专用 state 目录与执行身份，恢复后以锁、created/unchanged、退出码和最终报告验收。具体配置见<a href="/systems/shell-automation/automation/plus/practice/application#source">配套示例</a>。</p><p>教学版本族：Python 3.12 标准库；cron 常见五字段模型、launchd 与 Windows Task Scheduler 2.0 仅讲调度语义，不注册或运行任务。核对日期2026-10-17，不称为2026最新版。示例未执行，配置与命令需按目标环境验收。</p><h3 id="part-1-retry" tabindex="-1">可重试与不可重试 <a class="header-anchor" href="#part-1-retry" aria-label="Permalink to &quot;可重试与不可重试 {#part-1-retry}&quot;">​</a></h3><p>自动化 重试应按错误分类。锁冲突可稍后重新调度，日期非法应改输入，内容冲突应人工核对，权限错误应修正授权而不是无限重试。重试次数与退避需有界，避免每分钟失败生成无穷日志；本例不内建循环，让调用层看到真实退出码。</p><h3 id="part-1-recovery" tabindex="-1">中断恢复与批次账本 <a class="header-anchor" href="#part-1-recovery" aria-label="Permalink to &quot;中断恢复与批次账本 {#part-1-recovery}&quot;">​</a></h3><p>自动化 恢复先停触发、确认无活跃实例并保留证据，再核对目标、临时文件和锁。目标一致可重跑验证，目标冲突不自动覆盖。缺失日期清单由外部明确列出并逐个重放，不能把调度器最后运行时间当完整账本；本例每日期一个最终文件，但不保证多主机互斥。</p><h3 id="part-1-cleanup" tabindex="-1">专用目录的清理边界 <a class="header-anchor" href="#part-1-cleanup" aria-label="Permalink to &quot;专用目录的清理边界 {#part-1-cleanup}&quot;">​</a></h3><p>自动化 清理先确认绝对路径在例子目录的 state 内，且无其他任务使用。只删除本项目的report日期文件、.pending与空.lock；不要对计算得出的未知路径执行递归删除。脚本自己不做批量清理，也不删除已存在的冲突报告；恢复步骤在README列出，需读者未来在隔离环境自行确认。</p><h3 id="part-1-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-1-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-1-exercise}&quot;">​</a></h3><p>题目：恢复时state中有完整report-2026-10-17.json、半写的.pending与空.lock，且已确认无存活实例。目标内容与期望一致。列出保留/清理顺序，以及重跑是否会消费.pending。</p><p>参考解答：先停外部触发并保存三个对象的证据，核对state绝对路径、私有归属及普通文件/非链接类型；仅移除确认遗留的空.lock。重跑先比较最终报告，一致即unchanged，不读取或消费.pending，也不会因它存在就覆盖正式报告。待确认成功后可精确清理本例.pending；保留正式报告作为幂等证据，不递归删除state。</p><h3 id="part-1-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;核对资料 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/windows/win32/taskschd/taskschedulerschema-multipleinstancespolicy-settingstype-element" target="_blank" rel="noopener noreferrer">Microsoft 多实例策略</a></li><li><a href="https://developer.apple.com/library/archive/documentation/MacOSX/Conceptual/BPSystemStartup/Chapters/CreatingLaunchdJobs.html" target="_blank" rel="noopener noreferrer">Apple launchd 周期作业</a></li><li><a href="https://docs.python.org/3.12/library/time.html" target="_blank" rel="noopener noreferrer">Python 3.12 时间</a></li><li><a href="https://docs.python.org/3.12/library/os.html" target="_blank" rel="noopener noreferrer">Python 3.12 os 文件接口</a></li></ul><h2 id="part-2" tabindex="-1">漏跑、重复执行与产物异常排障 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;漏跑、重复执行与产物异常排障 {#part-2}&quot;">​</a></h2><p>本节沿锁、created/unchanged、退出码和最终报告定位失败层；先确认批次日期、专用 state 目录与执行身份，与<a href="/systems/shell-automation/automation/plus/practice/application#source">配套示例</a>逐项对照，再选择最小修复。</p><h3 id="part-2-missing" tabindex="-1">任务没触发与任务失败 <a class="header-anchor" href="#part-2-missing" aria-label="Permalink to &quot;任务没触发与任务失败 {#part-2-missing}&quot;">​</a></h3><p>自动化 任务没触发要看调度器历史、时区、账户登录和休眠条件；任务启动后退出非零要看参数、权限与程序stderr。两者证据不同。仅看到空日志不能判断未运行，日志路径可能错误或无权限；本项目直接输出简短结果，调用层应负责保存和轮转。</p><h3 id="part-2-duplicate" tabindex="-1">重复执行与结果冲突 <a class="header-anchor" href="#part-2-duplicate" aria-label="Permalink to &quot;重复执行与结果冲突 {#part-2-duplicate}&quot;">​</a></h3><p>自动化 重复执行要比较幂等键、启动来源和并发窗口。不同日期生成不同文件是预期，同日期 unchanged 是可重放；同日期不同内容是协议冲突。发现锁不自动删，确认无进程再恢复；若有多个主机，需换成能覆盖所有调用者的一致性机制，不能共享本地mkdir经验。</p><h3 id="part-2-permissions" tabindex="-1">路径覆盖与运行身份 <a class="header-anchor" href="#part-2-permissions" aria-label="Permalink to &quot;路径覆盖与运行身份 {#part-2-permissions}&quot;">​</a></h3><p>自动化 PermissionError 先核对任务实际身份、父目录权限、现有目标类型与受控路径。字符串前缀检查不能排除链接或Windows重解析点；示例逐段拒绝相关对象，但仍依赖私有稳定父目录，不能对抗恶意同身份并发替换。不要为了通过任务把目录设为所有人可写。</p><h3 id="part-2-exercise" tabindex="-1">练习与参考解答 <a class="header-anchor" href="#part-2-exercise" aria-label="Permalink to &quot;练习与参考解答 {#part-2-exercise}&quot;">​</a></h3><p>题目：调度器记录进程已启动，stderr显示conflicting report，退出4；另一个时段没有进程启动记录且主机休眠。两者能否统一用无限重试修复？分别需要哪项证据？</p><p>参考解答：不能。退出4说明任务运行后发现同日期目标内容冲突，须保留原报告并人工比较batchDate/schemaVersion与期望，不自动覆盖。没有启动记录且主机休眠属于触发层调查，应核对调度时间、时区、休眠/补跑语义和任务历史，明确缺失批次后再重放。无限重试既不能解释冲突，也不能证明漏批次已经补齐。</p><h3 id="part-2-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-2-sources" aria-label="Permalink to &quot;核对资料 {#part-2-sources}&quot;">​</a></h3><p>本节沿用<a href="#part-1-sources">本页资料与示例入口</a>。</p><h2 id="part-3" tabindex="-1">重复触发与补跑冲突的复盘 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;重复触发与补跑冲突的复盘 {#part-3}&quot;">​</a></h2><p>以下演练将日期报告任务的变更、失败证据和恢复验收串起来；先熟悉<a href="/systems/shell-automation/automation/plus/practice/application#source">配套示例</a>中的批次日期、专用 state 目录与执行身份。演练未执行。</p><h3 id="part-3-incident-scenario" tabindex="-1">故障场景与影响 <a class="header-anchor" href="#part-3-incident-scenario" aria-label="Permalink to &quot;故障场景与影响 {#part-3-incident-scenario}&quot;">​</a></h3><p>同一批次被调度器和人工补跑同时触发，出现锁冲突或两份不一致报告。</p><p>先记录首次异常时间、受影响对象和最近变更，区分个别对象失败与整条管理链路异常。以下是排查演练，不是已发生事故的实测记录。</p><h3 id="part-3-incident-evidence" tabindex="-1">按证据定位原因 <a class="header-anchor" href="#part-3-incident-evidence" aria-label="Permalink to &quot;按证据定位原因 {#part-3-incident-evidence}&quot;">​</a></h3><ol><li>以批次键关联计划触发、实际进程和最终产物，区分重试与不同批次。</li><li>核对锁持有者与进程状态，检查超时后进程是否仍运行，不因锁文件年龄直接删除。</li><li>比较提交记录、临时文件与正式产物；检查失败是否发生在写入前、写入中或成功响应丢失后。</li></ol><h3 id="part-3-incident-recovery" tabindex="-1">恢复步骤与验收 <a class="header-anchor" href="#part-3-incident-recovery" aria-label="Permalink to &quot;恢复步骤与验收 {#part-3-incident-recovery}&quot;">​</a></h3><p>停止新增触发并确认活跃执行者，按任务约定恢复到可重新提交状态。已提交批次应识别为完成，未完成批次使用同一业务键补跑。</p><p>验收：连续与并发触发同一批次都不会产生重复业务结果；中断后补跑能收敛到一份完整产物。分别记录调度状态、进程退出码和业务提交证据。</p><p>将触发条件、直接原因、修复动作、恢复证据和后续检查写入同一份复盘，明确每项后续工作的负责人。机制参考：<a href="https://learn.microsoft.com/en-us/windows/win32/taskschd/task-scheduler-start-page" target="_blank" rel="noopener noreferrer">官方说明</a>。</p><h3 id="part-3-reasoning" tabindex="-1">五项契约自检 <a class="header-anchor" href="#part-3-reasoning" aria-label="Permalink to &quot;五项契约自检 {#part-3-reasoning}&quot;">​</a></h3><p>给任何自动化任务写出批次键、身份、时间语义、并发策略和成功产物。少一项就很难解释“重跑是否安全”。本例日期键与确定内容提供单目录报告的重放，锁只覆盖同目录协作实例，退出码则区分拒绝原因。</p><h3 id="part-3-exercise" tabindex="-1">独立故障推演 <a class="header-anchor" href="#part-3-exercise" aria-label="Permalink to &quot;独立故障推演 {#part-3-exercise}&quot;">​</a></h3><p>不执行项目，推演在临时文件写一半、replace前、replace后但输出前、finally前被强杀四个窗口。分别判断产物是否完整、下次是否能进入以及要保留哪些证据；再说明调度器IgnoreNew能否覆盖另一个手工启动实例。</p><h3 id="part-3-answers" tabindex="-1">参考解答与范围 <a class="header-anchor" href="#part-3-answers" aria-label="Permalink to &quot;参考解答与范围 {#part-3-answers}&quot;">​</a></h3><p>replace前最终报告未改变，临时文件可能部分；replace后报告可完整存在但调用者未见成功，重放应识别 unchanged；强杀可能留下锁，需确认无实例后恢复。IgnoreNew只覆盖同一调度任务。分布式锁、长工作流、跨资源事务和真正断电测试均属于后续，不将本例扩展成生产调度平台。</p><h3 id="part-3-sources" tabindex="-1">核对资料 <a class="header-anchor" href="#part-3-sources" aria-label="Permalink to &quot;核对资料 {#part-3-sources}&quot;">​</a></h3><p>本节沿用<a href="#part-1-sources">本页资料与示例入口</a>。</p>',47)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
